    "title": "પરમહંસ બાબાજી અને ભક્તિસિદ્ધાંત સરસ્વતી ઠાકુરના આધ્યાત્મિક ગુરુ",
    "sampradaya": "બ્રહ્મ-માધ્વ-ગૌડીય",
    "years": "1830નો દાયકો – 17 નવેમ્બર 1915 (ઉત્થાન એકાદશી)",
    "appearance": {
      "date": "1830નો દાયકો",
      "place": "વાગ્યાના, ફરીદપુર, પૂર્વ બંગાળ"
    },
    "disappearance": {
      "date": "17 નવેમ્બર 1915 (ઉત્થાન એકાદશી)",
      "place": "કુલિયા, નવદ્વીપ"
    },
    "summary": "વૈરાગ્યની સાકાર મૂર્તિ, એ નિરક્ષર પરમહંસ જેમણે ભક્તિસિદ્ધાંત સરસ્વતી ઠાકુરને દીક્ષા આપી અને નિર્ભય ઉદાહરણ દ્વારા દંભ વિરુદ્ધ શિક્ષણ આપ્યું.",
    "biography": [
      {
        "p": "વૈરાગ્યની સાકાર મૂર્તિ શ્રીલ ગૌરકિશોર દાસ બાબાજી મહારાજનું પ્રાગટ્ય 1830ના દાયકામાં પૂર્વ બંગાળના ફરીદપુરના વાગ્યાનામાં થયું. વીસ વર્ષથી વધુ સમય સુધી તેઓ અનાજના દલાલ અને ગૃહસ્થ હતા. પત્નીના અવસાન પછી તેમણે વૃંદાવનમાં ભાગવત દાસ બાબાજી પાસેથી બાબાજી દીક્ષા લીધી અને આશરે ત્રીસ વર્ષ વ્રજમાં વિચર્યા. 1897થી તેઓ નવદ્વીપમાં રહ્યા; સૂકું અનાજ ભિક્ષામાં માગતા, ફેંકી દેવાયેલાં વસ્ત્રો પહેરતા અને દરેક સુખ-સુવિધાનો ઇનકાર કરતા. ભૌતિક હેતુથી આવતા લોકોને દૂર રાખવા તેઓ એક વાર શૌચાલયમાં રહ્યા. જીવનનાં અંતિમ વર્ષોમાં અંધ હોવા છતાં તેમણે નિર્ભયતાથી દંભને ઉઘાડો પાડ્યો, અને ભક્તિવિનોદ ઠાકુરને પોતાના શિક્ષા-ગુરુ તરીકે સ્વીકાર્યા. તેમના એકમાત્ર દીક્ષિત શિષ્ય શ્રીલ ભક્તિસિદ્ધાંત સરસ્વતી ઠાકુર હતા. 16 નવેમ્બર 1915ના રોજ કુલિયામાં તેમણે પ્રયાણ કર્યું ત્યારે ભક્તિસિદ્ધાંત સરસ્વતીએ નફા માટે તેમનો દેહ ઇચ્છનારા હરીફ બાબાજીઓનો સામનો કર્યો અને સ્વયં તેમને સમાધિ આપી."
      },
      {
        "p": "તેઓ એકાદશીએ પાણી પણ લીધા વિના સંપૂર્ણ ઉપવાસ કરતા, અને કહેતા કે જે ભોજન (સ્વાદિષ્ટ આહાર) ઇચ્છે છે તે પોતાનું ભજન બગાડે છે. સ્વાનંદ-સુખદ-કુંજમાં ભક્તિવિનોદ ઠાકુરના ભાગવતમ્ વર્ગો સાંભળવા તેઓ નિયમિત આવતા. ભક્તિસિદ્ધાંત સરસ્વતીએ દીક્ષા માગી ત્યારે તેમને સ્વીકારતાં પહેલાં તેમણે ત્રણ વાર પરીક્ષા લીધી. એક વાર બાબાજીના વેશમાં રહેતા દંભીઓથી શરમાઈને તેમણે સુંદર ધોતી અને શાલ પહેરી, અને કહ્યું કે લંગોટી પહેરીને અનૈતિક જીવન જીવવા કરતાં સજ્જનની જેમ વસ્ત્રો પહેરવાં વધુ સારાં છે. તેમને મળતું દાન છાનામાના પોતાના સસરાને મોકલનાર એક સેવકનો તેમણે ત્યાગ કર્યો."
      }
    ],
