        "p": "એકાંત ભજનના અનુકરણને બદલે ભક્તોના સંગમાં પવિત્ર નામનો જપ કરો; ભાવાવેશ છુપાવવો જોઈએ, દેખાડવો નહીં; અને સાધુનાં કઠોર વચનો માયાને દૂર કરવાની ઔષધિ છે."
