    "summary": "છ ગોસ્વામીઓના અગ્રણી અને ભક્તિ-રસામૃત-સિંધુના રચયિતા, જેમના અનુયાયીઓ, રૂપાનુગોમાં, દરેક ગૌડીય વૈષ્ણવનો સમાવેશ થાય છે.",
    "biography": [
      {
        "p": "શ્રીલ રૂપ ગોસ્વામી (1489-1564), કૃષ્ણ-લીલામાં રૂપ-મંજરી, છ ગોસ્વામીઓમાં અગ્રણી છે, અને ભગવાન ચૈતન્યના બધા અનુયાયીઓ રૂપાનુગ, એટલે કે રૂપના અનુયાયી કહેવાય છે. પોતાના મોટા ભાઈ સનાતન સાથે તેમણે બંગાળના શાસક હુસેન શાહના મંત્રી (દબીર ખાસ) તરીકે સેવા આપી, જ્યાં સુધી રામકેલીમાં મહાપ્રભુ સાથેની મુલાકાતે તેમને સર્વસ્વ ત્યાગવાની પ્રેરણા ન આપી. પ્રયાગના દશાશ્વમેધ ઘાટ પર ભગવાને સ્વયં દસ દિવસ સુધી તેમને ભક્તિ-વિજ્ઞાનનો ઉપદેશ આપ્યો, અને લુપ્ત થયેલાં પવિત્ર સ્થાનો પ્રગટ કરવા તથા ભક્તિ-સાહિત્ય લખવા તેમને વૃંદાવન મોકલ્યા. 1516માં વ્રજમાં સ્થાયી થઈને તેમણે શ્રી ગોવિંદદેવને પ્રગટ કર્યા અને આશરે એક લાખ શ્લોકો રચ્યા, જેમાં ‘ભક્તિ-રસામૃત-સિંધુ’, ‘ઉજ્જ્વલ-નીલમણિ’, ‘ઉપદેશામૃત’, ‘વિદગ્ધ-માધવ’ અને ‘લલિત-માધવ’નો સમાવેશ થાય છે. મહાપ્રભુના તિરોભાવ પછી તેમણે નવા ગૌડીય આંદોલનને એક રાખ્યું. તેમની સમાધિ રાધા-દામોદર મંદિરમાં છે, એ ઓરડાઓની બાજુમાં જ્યાં પાછળથી શ્રીલ પ્રભુપાદ રહ્યા."
      },
      {
        "p": "ભગવાનને મળ્યા પહેલાં રૂપે ‘હંસદૂત’ લખી લીધું હતું. 1514માં રામકેલીમાં મુલાકાત પછી તેમણે પોતાની સંપત્તિ દાનમાં આપી દીધી, પ્રયાગમાં ફરી ભગવાનને મળ્યા, અને પછી પુરીમાં તેમની સાથે રહ્યા, જ્યાં રામાનંદ રાય અને ભગવાને તેમનાં નાટકોના શ્લોકોનો આસ્વાદ લીધો. વૃંદાવનમાં રાધા-દામોદર મંદિરની તેમની ભજન-કુટિર અને નંદગ્રામ પાસે ટેર કદંબની તેમની કુટિર તેમના લેખનનાં કેન્દ્રો બન્યાં. 1590માં રાજા માનસિંહે બંધાવેલું ગોવિંદજી મંદિર તેમણે પ્રગટ કરેલા વિગ્રહ માટે ઊભું કરવામાં આવ્યું હતું."
      }
    ],
    "teachings": [
      {
        "p": "ભક્તિ આત્માનો શાશ્વત ધર્મ છે; ભક્તિમય સેવા શ્રદ્ધાથી ભગવત્પ્રેમ સુધી તબક્કાવાર વિકસે છે; ભક્તિને અનુકૂળ હોય તે બધું સ્વીકારવું અને પ્રતિકૂળ હોય તે બધું ત્યજવું; અને રાગાનુગા ભક્તિ વ્રજવાસીઓના ભાવને અનુસરે છે."
      }
    ],
