    "title": "ગોસ્વામીઓ પછીની પેઢીના આચાર્ય અને પ્રથમ ગ્રંથ-વિતરણ મંડળીના નેતા",
    "sampradaya": "બ્રહ્મ-માધ્વ-ગૌડીય",
    "years": "પ્રાગટ્ય વૈશાખ પૂર્ણિમા, આશરે 1515-1519",
    "appearance": {
      "date": "વૈશાખ પૂર્ણિમા, આશરે 1515-1519",
      "place": "ચાખંડી, બંગાળ"
    },
    "summary": "ગોપાલ ભટ્ટ ગોસ્વામીના શિષ્ય અને જીવ ગોસ્વામીના વિદ્યાર્થી, જેઓ ગોસ્વામીઓના ગ્રંથો બંગાળ લાવ્યા અને વન વિષ્ણુપુરના રાજા બીર હમ્બીરનું હૃદય-પરિવર્તન કર્યું.",
    "biography": [
      {
        "p": "શ્રી શ્રીનિવાસ આચાર્યનો જન્મ મહાપ્રભુના આશીર્વાદથી બંગાળના ચાખંડીમાં ગંગાધર ભટ્ટાચાર્ય, જેઓ ચૈતન્ય દાસ કહેવાતા, અને લક્ષ્મીપ્રિયાને ત્યાં થયો, અને તેમને ભગવાનના ભાવાવેશના મૂર્તિમંત સ્વરૂપ તરીકે વર્ણવવામાં આવે છે (કૃષ્ણ-લીલામાં મણિ-મંજરી). તેમણે ગોપાલ ભટ્ટ ગોસ્વામી પાસેથી દીક્ષા લીધી અને જીવ ગોસ્વામી પાસે તાલીમ પામ્યા, જેમણે તેમને ‘આચાર્ય’ ઉપાધિ આપી. તેમણે ગૌડીય ઇતિહાસની પ્રથમ ગ્રંથ-વિતરણ મંડળીનું નેતૃત્વ કર્યું અને ગોસ્વામીઓની હસ્તપ્રતો બળદગાડામાં પૂર્વ તરફ લઈ ગયા. વન વિષ્ણુપુર પાસે ગ્રંથો ચોરાયા ત્યારે તેમણે તે પાછા મેળવ્યા અને ચોર, રાજા બીર હમ્બીરનું હૃદય-પરિવર્તન કર્યું, જેઓ તેમના શિષ્ય બન્યા. રામચંદ્ર કવિરાજ જેવા શિષ્યો સાથે તેમણે સમગ્ર બંગાળમાં પ્રચાર કર્યો, કીર્તનની મનોહરશાહી શૈલીનો પ્રારંભ કર્યો, અને નરોત્તમ તથા શ્યામાનંદ સાથે મળીને ખેતુરીના મહાન ઉત્સવનું આયોજન કર્યું. તેમણે છ ગોસ્વામીઓની જાણીતી પ્રાર્થના ‘ષડ્-ગોસ્વામી-અષ્ટક’ની રચના કરી."
      },
      {
        "p": "કાટવામાં મહાપ્રભુનો સંન્યાસ જોયા પછી તેમના પિતા ગંગાધર એટલા ભાવવિભોર થઈ ગયા કે તેઓ ચૈતન્ય દાસ તરીકે ઓળખાવા લાગ્યા, અને ભગવાને દંપતીને પુત્રના આશીર્વાદ આપ્યા. યુવાનીમાં શ્રીનિવાસ નરહરિ સરકાર, ગદાધર પંડિત અને જાહ્નવા દેવીને મળ્યા. ‘પ્રેમ-વિલાસ’ તેમના 117 શિષ્યોનાં નામ આપે છે, જેમાં રામચંદ્ર કવિરાજ અને તેમના ભાઈ ગોવિંદ કવિરાજનો સમાવેશ થાય છે. રામચંદ્ર સાથે વૃંદાવનની બીજી મુલાકાત વખતે ગોપાલ ભટ્ટે તેમને રાધા-રમણની પૂજા સંભાળવાને બદલે બંગાળમાં પ્રચાર ચાલુ રાખવા કહ્યું. તેમના અનુયાયીઓએ તેમના પ્રયાણ વિશે કંઈ નોંધ્યું નથી."
      }
    ],
