    "summary": "ખેતુરીના રાજકુમાર, જેઓ લોકનાથ ગોસ્વામીના એકમાત્ર શિષ્ય બન્યા, ખેતુરીનો મહાન ઉત્સવ યોજ્યો અને ગૌડીય વૈષ્ણવોને તેમનાં સૌથી પ્રિય ગીતો આપ્યાં.",
    "biography": [
      {
        "p": "શ્રીલ નરોત્તમ દાસ ઠાકુર (1534-1611), કૃષ્ણ-લીલામાં ચંપક-મંજરી, ખેતુરીમાં રાજા કૃષ્ણાનંદ દત્ત અને નારાયણી દેવીના પુત્ર, રાજકુમાર તરીકે જન્મ્યા હતા. મહાપ્રભુએ તેમના માટે પોતાનો પ્રેમ પદ્મા નદીમાં રાખ્યો હતો, અને કિશોર નરોત્તમે ત્યાં સ્નાન કર્યું ત્યારે તેમનો વર્ણ સુવર્ણ જેવો થઈ ગયો. પિતાના રક્ષકોથી છટકીને તેઓ ચાલતા વૃંદાવન ગયા, જ્યાં તેઓ લોકનાથ ગોસ્વામીના એકમાત્ર શિષ્ય બન્યા અને જીવ ગોસ્વામી પાસે અભ્યાસ કર્યો, જેમણે તેમને ‘ઠાકુર’ ઉપાધિ આપી. શ્રીનિવાસ અને શ્યામાનંદ સાથે તેઓ ગોસ્વામીઓના ગ્રંથો પૂર્વ તરફ લાવ્યા. ખેતુરીમાં તેમણે પ્રથમ મહાન ગૌર પૂર્ણિમા ઉત્સવ યોજ્યો, જ્યાં મહાપ્રભુ અને તેમના પાર્ષદો તેમના કીર્તનમાં નૃત્ય કરતા દેખાયા, અને કીર્તનની ગરાણહાટી શૈલી સ્થાપી. તેમનાં બંગાળી ગીતો, વિશેષ કરીને ‘પ્રાર્થના’ અને ‘પ્રેમ-ભક્તિ-ચંદ્રિકા’, બધે ભક્તો ગાય છે. કહેવાય છે કે પ્રયાણ સમયે તેમનો દેહ ગંગામાં દૂધ બનીને ઓગળી ગયો, જેની સ્મૃતિ દુગ્ધ-સમાધિમાં સચવાયેલી છે."
      },
      {
        "p": "શિશુ અવસ્થામાં તેમણે કૃષ્ણને અર્પણ ન કરાયેલું અન્ન લેવાની ના પાડી. વૃંદાવનમાં દીક્ષા પહેલાં તેમણે બે વર્ષ સુધી છાનામાના લોકનાથની સેવા કરી, અને રાધારાણીએ સ્વપ્નમાં તેમને દૂધ ઉકાળવાની શાશ્વત સેવા આપી, જેના દાઝ્યાનાં નિશાન તેમના હાથ પર દેખાયાં. તેમના જન્મને કારણે તેમનો વિરોધ કરનારા અનેક બ્રાહ્મણોને તેમના શિષ્યો ગંગાનારાયણ ચક્રવર્તી અને રામચંદ્ર કવિરાજે પરાસ્ત કર્યા, અને રાજા નરસિંહ તથા વિદ્વાન રૂપનારાયણ જેવા અગ્રણીઓ તેમને શરણે આવ્યા. ‘પ્રેમ-વિલાસ’ તેમના 123 શિષ્યોની યાદી આપે છે."
      }
    ],
