    "name": "શ્રી શ્યામાનંદ પ્રભુ",
    "shortName": "શ્યામાનંદ પ્રભુ",
    "title": "ઓડિશાના આચાર્ય, જેમને રાધારાણીનું નૂપુર મળ્યું",
    "sampradaya": "બ્રહ્મ-માધ્વ-ગૌડીય",
    "years": "પ્રાગટ્ય આશરે 1535",
    "appearance": {
      "date": "આશરે 1535",
      "place": "ધારેંદા, મિદનાપુર, ઓડિશા"
    },
    "disappearance": {
      "place": "નરસિંહપુર, ઓડિશા"
    },
    "summary": "હૃદય ચૈતન્યના શિષ્ય અને જીવ ગોસ્વામીના વિદ્યાર્થી, જેમને રાધારાણીનું નૂપુર અને શ્યામસુંદર વિગ્રહ મળ્યા, અને જેમણે સમગ્ર ઓડિશામાં ગૌડીય વૈષ્ણવ ધર્મ ફેલાવ્યો.",
    "biography": [
      {
        "p": "શ્રી શ્યામાનંદ પ્રભુનો જન્મ આશરે 1535માં ઓડિશાના ધારેંદામાં કૃષ્ણ મંડલ અને દુરિકાને ત્યાં થયો, જેમણે તેમનું નામ દુઃખી રાખ્યું. ગૌરીદાસ પંડિતના શિષ્ય હૃદય ચૈતન્ય પાસેથી તેમણે દીક્ષા લીધી અને તેમને વૃંદાવનમાં જીવ ગોસ્વામી પાસે અભ્યાસ માટે મોકલવામાં આવ્યા. એક સવારે કુંજમાં વાળતાં તેમને શ્રીમતી રાધારાણીનું સુવર્ણ નૂપુર મળ્યું. તેમણે તે પાછું આપ્યું ત્યારે લલિતા-સખીએ તેનાથી તેમના કપાળ પર ચિહ્ન કર્યું, જે શ્યામાનંદી તિલકનો ઉદ્ગમ છે. તેમણે તેમનું નામ શ્યામાનંદ રાખ્યું, એટલે કે શ્યામને આનંદ આપનાર, અને રાધારાણીએ તેમને શ્રી શ્યામસુંદર વિગ્રહ આપ્યા, જેમની પૂજા આજે વૃંદાવનના રાધા-શ્યામસુંદર મંદિરમાં થાય છે. શ્રીનિવાસ આચાર્ય અને નરોત્તમ દાસ ઠાકુર સાથે તેઓ ગોસ્વામીઓના ગ્રંથો પૂર્વ તરફ લઈ ગયા. પોતાના શિષ્ય રસિકાનંદ સાથે તેમણે સમગ્ર ઓડિશામાં ગૌડીય વૈષ્ણવ ધર્મ ફેલાવ્યો; રાજાઓ અને જમીનદારોનું હૃદય-પરિવર્તન કર્યું, પશુબલિ બંધ કરાવી અને કીર્તનની રેનેટી શૈલી લોકપ્રિય બનાવી. તેમની સમાધિ ઓડિશાના નરસિંહપુરમાં છે."
      },
      {
        "p": "વૃંદાવન જતાં પહેલાં તેમણે સમગ્ર ભારતમાં વ્યાપક તીર્થયાત્રા કરી. 1578માં નિધુવનમાં રાધા-શ્યામસુંદર પ્રાપ્ત થયા, અને 1580માં તેમણે ભરતપુરના રાજાના ખજાનામાં પ્રગટ થયેલાં રાધારાણી (લાલીજી) સાથે શ્યામસુંદરના દિવ્ય વિવાહની વ્યવસ્થા કરી. શિષ્યના નામ અને તિલકમાં થયેલા ફેરફારથી તેમના ગુરુ હૃદય ચૈતન્ય પહેલાં ક્રોધિત થયા, પરંતુ શ્યામાનંદના નમ્ર શરણાગતિભાવે તેમનું મન જીતી લીધું. ઓડિશામાં તેમણે અને રસિકાનંદે ઘાટશિલા અને ગોવિંદપુરના જમીનદારો તથા મયૂરભંજના રાજા જેવા શાસકોનું હૃદય-પરિવર્તન કર્યું. પ્રયાણ પહેલાં તેમણે રસિકાનંદને પોતાના ઉત્તરાધિકારી નીમ્યા."
      }
    ],
